 public void Tick(float dt){if(final3DTransition){AdvanceFinalTransition(dt);return;}time+=dt;AdvanceExclusive(dt);if(state!=ScreenState.Playing)return;dashCooldown=Mathf.Max(0,dashCooldown-dt);dashTimer=Mathf.Max(0,dashTimer-dt);if(Input.GetKeyDown(KeyCode.Space)&&dashCooldown<=0){dashCooldown=heroIndex==3?2.2f:3;dashTimer=.22f;invincible=.3f;BeginNinjaShadow();Play(dashSound);Burst(pos,new Color(.5f,.95f,1),1.2f,.25f,7);}
  invincible=Mathf.Max(0,invincible-dt);regenTimer+=dt;if(regenTimer>1){regenTimer=0;hp=Mathf.Min(maxHp,hp+.15f+passives[3]*.2f+runRelics.regen);}
  var move=new Vector2(Input.GetAxisRaw("Horizontal"),Input.GetAxisRaw("Vertical"));if(!manualAim&&Input.GetMouseButton(0)&&!OverHud()){Vector2 target=ArenaPointFromScreen(Input.mousePosition);move=target-pos;if(move.magnitude<.15f)move=Vector2.zero;}
  move=Vector2.ClampMagnitude(move,1);if(move.sqrMagnitude>.01f)facing=move.normalized;pos+=(dashTimer>0?facing*16:move*Speed*(playerChill>0?.65f:1))*dt;float edge=campaignActive?25:48;pos.x=Mathf.Clamp(pos.x,-edge,edge);pos.y=Mathf.Clamp(pos.y,-edge,edge);if(final3DActive)pos=finalOrigin+Vector2.ClampMagnitude(pos-finalOrigin,19);UpdateArchetype(dt,move);AnimateHero(dt,move);hero.sortingOrder=Depth(pos);hero.flipX=manualAim?lastAimDirection.x<0:facing.x<0;hero.color=invincible>0?new Color(1,1,1,.45f+Mathf.PingPong(time*10,.5f)):Color.white;
  shake=Mathf.Max(0,shake-dt*2);var cp=Vector2.Lerp(cam.transform.position,pos,dt*7)+UnityEngine.Random.insideUnitCircle*shake;if(!final3DVisible)cam.transform.position=new Vector3(cp.x,cp.y,-10);ReadAimPointer();if(manualAim)hero.flipX=lastAimDirection.x<0;if(Input.GetKeyDown(KeyCode.Q))TryExclusive();if(state!=ScreenState.Playing)return;
  SpawnWaves(dt);if(final3DTransition)return;UpdateRescue(dt);UpdateDragon(dt);if(state!=ScreenState.Playing)return;RefreshCombos();UpdateWeapons(dt);if(state!=ScreenState.Playing)return;UpdateEnemies(dt);if(state!=ScreenState.Playing)return;UpdateShots(dt);if(state!=ScreenState.Playing)return;UpdateLoot(dt);UpdateEffects(dt);UpdateAnimationDetails(dt);if(state==ScreenState.Playing)UpdateHazards(dt);if(state==ScreenState.Playing)UpdateElements(dt);
