 bool OverHud(){float scale=Mathf.Min(UnityEngine.Screen.width/1280f,UnityEngine.Screen.height/720f);float top=(UnityEngine.Screen.height-720*scale)/2;float y=(UnityEngine.Screen.height-Input.mousePosition.y-top)/scale;return y<152||y>590||LabPointerBlocked();}
