 void SpawnWaves(float dt){if(campaignActive){SpawnCampaignWaves(dt);return;}if(buildLabActive)return;if(elementTraining){spawnTimer-=dt;if(spawnTimer<=0&&enemies.Count<6){spawnTimer=3;SpawnEnemy(0,false);}return;}if(final3DActive&&!final3DTransition){SpawnEclipseWaves(dt);return;}float progress=time/Duration;spawnTimer-=dt;if(spawnTimer<=0&&enemies.Count<(final3DActive?48:230)){spawnTimer=Mathf.Lerp(.65f,.12f,progress);int count=1+(int)(progress*3);for(int i=0;i<count;i++){int type=time<30?0:UnityEngine.Random.value<.18f?1:UnityEngine.Random.value<progress*.25f?5:UnityEngine.Random.value<progress*.55f?2:0;SpawnEnemy(type,false);}}
  int interval=quickMode?60:180;if(time>=nextBoss*interval&&time<Duration){SpawnEnemy(new[]{3,6,7}[(nextBoss+stageIndex-1)%3],false);nextBoss++;Toast("Um guardião surgiu. Derrote-o para ganhar um baú!");}
  if(time>=Duration&&!finalSpawned){finalSpawned=true;finalBoss=SpawnEnemy(4,true);BeginFinal3D();}
 }
 Enemy SpawnEnemy(int type,bool final){float angle=UnityEngine.Random.value*Mathf.PI*2;float viewX=cam.orthographicSize*cam.aspect;float distance=final3DVisible?18:Mathf.Sqrt(viewX*viewX+cam.orthographicSize*cam.orthographicSize)+2;Vector2 p=pos+new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*distance;float progress=time/Duration;float health=IsBoss(type)&&type!=4?180+progress*550:type==4?1800:type==2?35:type==5?28:type==1?8:15;health*=1+progress*1.8f;var e=new Enemy{p=p,type=type,maxHp=health,hp=health,speed=type==1?2.3f:IsBoss(type)?1.15f:type==5?1.5f:type==2?.8f:1.15f,damage=IsBoss(type)?25:type==2?14:8,final=final};e.speed*=1+progress*.45f;ConfigureBiomeEnemy(e);e.sprite=Sprite(e.biome>=0?EnemyName(e):"Enemy",EnemyAppearance(e),p,IsBoss(type)?2.5f:1.15f,Color.white,Depth(p));e.animClock=enemies.Count*.137f%1;enemies.Add(e);return e;}
 void UpdateEnemies(float dt){for(int i=enemies.Count-1;i>=0;i--){var e=enemies[i];AdvanceEnemyFSM(e,dt);
  switch(e.aiState){
   case EnemyState.Dead: continue;
   case EnemyState.Training: UpdateDummy(e,dt);continue;
   case EnemyState.Frozen:
    e.frozen=Mathf.Max(0,e.frozen-dt);e.slow=Mathf.Max(0,e.slow-dt);e.flash=Mathf.Max(0,e.flash-dt);
    e.sprite.color=e.flash>0?new Color(1,.35f,.4f):new Color(.45f,.8f,1);continue;
   case EnemyState.Attacking: ExecuteEnemyAttack(e);break;
   case EnemyState.Chasing: break;
  }
  UpdateBossCharge(e,dt);Vector2 delta=pos-e.p;AnimateEnemy(e,dt,delta);e.slow=Mathf.Max(0,e.slow-dt);e.p+=BiomeMotion(e,delta)*e.speed*runRelics.enemySpeed*(activeCurse==1?1.2f:1)*(e.slow>0?.4f:1)*dt;if(final3DActive&&e.biome>=0)e.p=finalOrigin+Vector2.ClampMagnitude(e.p-finalOrigin,19);e.sprite.transform.position=e.p;e.sprite.sortingOrder=Depth(e.p);e.flash=Mathf.Max(0,e.flash-dt);e.sprite.color=e.flash>0?new Color(1,.35f,.4f):e.slow>0?new Color(.5f,.8f,1):e.phaseTwo?new Color(1,.7f,.6f):Color.white;
  if(delta.magnitude<(IsBoss(e.type)?1:.5f)&&invincible<=0){e.animAttack=.25f;hp=Mathf.Max(0,hp-e.damage*(activeCurse==2?1.3f:1)*IncomingMultiplier);invincible=.8f;shake=.2f;Play(hitSound);Burst(pos,new Color(1,.2f,.3f),1);if(hp<=0){EndRun(false);return;}}
  if(delta.magnitude>35&&!IsBoss(e.type)){float a=UnityEngine.Random.value*Mathf.PI*2;e.p=pos+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*18;}
 }}
 Enemy Nearest(){Enemy best=null;float distance=400;foreach(var e in enemies){float d=(e.p-pos).sqrMagnitude;if(d<distance){distance=d;best=e;}}return best;}
 void UpdateWeapons(float dt){if(state!=ScreenState.Playing)return;ReadManualAttack(dt);orbitTimer-=dt;for(int w=0;w<6;w++){int rank=weapons[w];if(rank==0){preparingPower[w]=false;powerPreparation[w]=0;continue;}cooldown[w]=Mathf.Max(0,cooldown[w]-dt);
  if(!CanPreparePower(w)){preparingPower[w]=false;powerPreparation[w]=0;manualAttackRequested[w]=false;if(w==2){orbitPowerReady=false;foreach(var orb in orbitVisuals)if(orb!=null)orb.enabled=false;}continue;}
  if(w==2&&orbitPowerReady){UpdateCrown(rank);if(state!=ScreenState.Playing){CancelPowerPreparation();return;}continue;}
  if(cooldown[w]>0)continue;
  if(!preparingPower[w]){if(!CanPreparePower(w))continue;BeginPowerPreparation(w);continue;}
  powerPreparation[w]=Mathf.Max(0,powerPreparation[w]-dt);if(powerPreparation[w]>.00001f)continue;preparingPower[w]=false;
  if(w==2){orbitPowerReady=true;manualAttackRequested[w]=false;if(manualAim)manualCrownRemaining=.38f;CastVisual();UpdateCrown(rank);if(state!=ScreenState.Playing){CancelPowerPreparation();return;}continue;}
  if(!CanPreparePower(w)){cooldown[w]=.1f;continue;}ReleasePower(w,rank);manualAttackRequested[w]=false;if(state!=ScreenState.Playing){CancelPowerPreparation();return;}cooldown[w]=WeaponPeriod(w);
 }if(orbitTimer<=0)orbitTimer=.35f;UpdatePowerPreparationVisual();}
 void UpdateCrown(int rank){int w=2,n=2+rank/2+(evolved[w]?3:0);float r=(1.5f+rank*.1f)*Area;for(int j=0;j<n;j++){float a=time*(evolved[w]?2.7f:1.8f)+j*Mathf.PI*2/n;Vector2 p=pos+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*r;OrbitVisual(j,p,evolved[w]?.48f:.32f);if(orbitTimer<=0){DamageArea(p,.55f*Area,(7+rank*3)*Power*(evolved[w]?2:1),false);if(state!=ScreenState.Playing)return;}}}
 void ReleasePower(int w,int rank){if(ReleaseSignature(w,rank))return;CastVisual();float bonus=evolved[w]?1.8f:1;float damage=(w==0?10+rank*4:w==1?8+rank*3:w==3?12+rank*4:w==4?15+rank*5:9+rank*4)*Power*bonus;
  if(w==0){var target=Nearest();int n=1+rank/3+(evolved[w]?2:0);for(int j=0;j<n;j++){Vector2 direction=WeaponDirection(pos,target);direction=Rotate(direction,(j-(n-1)/2f)*.16f);Fire(pos,direction*8,damage,.2f*Area,rank>=5?2:1,Catalog.Colors[w],2.5f,0);}}
  if(w==1){Vector2 aim=WeaponDirection(pos,Nearest());int n=1+rank/2;for(int j=0;j<n;j++)Fire(pos+aim*j*.13f,Rotate(aim,(j-(n-1)/2f)*.09f)*12,damage,.15f*Area,evolved[w]?9:2,Catalog.Colors[w],2.5f,1);}
  if(w==3){Vector2 aim=WeaponDirection(pos,PowerTarget(w));int n=evolved[w]?3:1;for(int j=0;j<n;j++)Fire(pos,Rotate(aim,(j-(n-1)*.5f)*.14f)*8,damage,.24f*Area,evolved[w]?3:1,Catalog.Colors[w],1.5f,0,Element.Ice);}
  if(w==4){int n=1+rank/2;for(int j=0;j<n&&(manualAim||enemies.Count>0);j++){var target=manualAim?null:PowerTarget(w);if(!manualAim&&target==null)break;Vector2 p=LightningPoint(target);Burst(p,Catalog.Colors[w],1.5f,.3f,4);DamageArea(p,evolved[w]?2*Area:.5f,damage,false);if(state!=ScreenState.Playing)return;ReactElement(p,1.1f,Element.Lightning,damage);}}
  if(w==5){Vector2 aim=WeaponDirection(pos,Nearest());int n=evolved[w]?12:3+rank/2;for(int j=0;j<n;j++){Vector2 dir=evolved[w]&&!manualAim?Rotate(Vector2.up,j*Mathf.PI*2/n):Rotate(aim,(j-(n-1)/2f)*.16f);Fire(pos,dir*5,damage,.35f*Area,5,Catalog.Colors[w],.55f+rank*.05f,5,Element.Fire);}}
 }
 Vector2 Rotate(Vector2 p,float a)=>new Vector2(p.x*Mathf.Cos(a)-p.y*Mathf.Sin(a),p.x*Mathf.Sin(a)+p.y*Mathf.Cos(a));
 void Fire(Vector2 p,Vector2 v,float damage,float radius,int pierce,Color color,float life=2.5f,int icon=-1,Element element=Element.None,bool hostile=false){if(shots.Count>350)return;var s=new Shot{p=p,v=v,damage=damage,radius=radius,pierce=pierce,life=life,element=element,hostile=hostile,visualKind=element==Element.Fire?5:icon>=0&&icon<6?icon:0};s.sprite=Sprite("Projectile",ArtBank.Ability(s.visualKind),p+Vector2.up*.35f,radius*3,element==Element.Fire||icon>=0?Color.white:color,800);if(element==Element.Ice)s.sprite.color=new Color(.3f,.9f,1);s.sprite.transform.rotation=Quaternion.Euler(0,0,Mathf.Atan2(v.y,v.x)*Mathf.Rad2Deg);shots.Add(s);}
 void UpdateShots(float dt){UpdateRelicFissures(dt);if(state!=ScreenState.Playing)return;for(int i=shots.Count-1;i>=0;i--){var s=shots[i];s.life-=dt;s.age+=dt;s.p+=s.v*dt;s.sprite.sprite=s.relicFxRow>=0?ArtBank.AttackRelicFx(s.relicFxRow,ArtBank.Frame(s.age,12)):s.lunarArrow?SignatureArt.Arrow:ArtBank.Ability(s.visualKind,ArtBank.Frame(s.age,12));s.sprite.transform.position=s.p+Vector2.up*.35f;
  if(s.hostile){if((s.p-pos).sqrMagnitude<Mathf.Pow(s.radius+.35f,2)){if(invincible<=0){HurtPlayer(s.damage);if(s.element==Element.Fire)BurnPlayer(3,3);}s.pierce=0;ReactElement(s.p,.7f,s.element,s.damage,s.hostile);}}
  else for(int j=enemies.Count-1;j>=0;j--){var e=enemies[j];if(!s.hit.Contains(e)&&(e.p-s.p).sqrMagnitude<Mathf.Pow(s.radius+(IsBoss(e.type)?.8f:.35f),2)){s.hit.Add(e);if(s.splitOnHit)SplitRelicArrow(s);if(s.element==Element.Fire)BurnEnemy(e,3,Mathf.Clamp(s.damage*.18f,2,7));if(s.element==Element.Ice){FreezeEnemy(e);ReactElement(s.p,.65f,s.element,s.damage,false,false);Burst(e.p+Vector2.up*.4f,new Color(.35f,.85f,1),.8f,.2f,6);}else ReactElement(s.p,.65f,s.element,s.damage,s.hostile);Damage(e,s.damage);s.pierce--;if(s.pierce<=0)break;}}
  if(s.life<=0||s.pierce<=0){if(s.element!=Element.None&&s.element!=Element.Ice)ReactElement(s.p,.65f,s.element,s.damage,s.hostile);Dispose(s.sprite.gameObject);shots.RemoveAt(i);}
 }}
 void DamageArea(Vector2 center,float radius,float damage,bool slow){for(int i=enemies.Count-1;i>=0;i--){var e=enemies[i];if((e.p-center).sqrMagnitude<radius*radius){if(slow)FreezeEnemy(e);Damage(e,damage);}}}
 void Damage(Enemy e,float damage){if(e==null||e.aiState==EnemyState.Dead)return;if(e==markedEnemy&&exclusiveBuff>0)damage*=1.75f;if(e.trainingDummy){RecordLabDamage(damage);e.hp=e.maxHp;e.flash=.1f;return;}e.hp-=damage;e.flash=.09f;if(e.hp>0){TryBossPhase(e);return;}e.aiState=EnemyState.Dead;CancelBiomeWindup(e);if(e.rescueGuard)CompleteRescue();var p=e.p;int type=e.type;bool final=e.final;PlayDeath(e);if(e.status!=null)Dispose(e.status.gameObject);Dispose(e.sprite.gameObject);enemies.Remove(e);kills++;runCoins+=IsBoss(type)?20:UnityEngine.Random.value<.13f?1:0;SpawnLoot(p,0,IsBoss(type)?30:type==2?3:type==5?2:1);Burst(p,new Color(.9f,.5f,.4f),.6f,.18f);if(IsBoss(type)){UnlockCurse(type);if(!final)SpawnLoot(p,1,type);DropBossRelic(type,p,final);}if(UnityEngine.Random.value<.007f)SpawnLoot(p,2,25);if(UnityEngine.Random.value<.003f)SpawnLoot(p,3,0);RecordDragonDefeat(type);if(final){if(campaignActive)QueueStageRescue();else {EndRun(true);if(!elementTraining&&!final3DDemo)finalBonusPending=true;}}}
 void SpawnLoot(Vector2 p,int kind,float value){if(kind==0&&loot.Count>220){Loot nearest=null;float dist=float.MaxValue;foreach(var l in loot)if(l.kind==0&&(l.p-p).sqrMagnitude<dist){nearest=l;dist=(l.p-p).sqrMagnitude;}if(nearest!=null){nearest.value+=value;return;}}
  Color color=kind==2?new Color(1,.35f,.4f):kind==3?new Color(1,.8f,.2f):Color.white;var l2=new Loot{p=p,kind=kind,value=value,animClock=Mathf.Abs(p.x*.17f+p.y*.13f)%1};l2.sprite=Sprite("Loot",kind==4?ArtBank.Relic((int)value):ArtBank.Loot(kind),p,kind==1?.95f:kind==4?.8f:.5f,Color.white,-10);loot.Add(l2);}
 void UpdateLoot(float dt){if(buildLabActive)return;float reach=1.4f+passives[2]*.5f+(HasCombo(2)?1.5f:0);for(int i=loot.Count-1;i>=0;i--){var l=loot[i];l.animClock+=dt;l.sprite.sprite=l.kind==4?ArtBank.Relic((int)l.value):ArtBank.Loot(l.kind,l.kind==1?0:ArtBank.Frame(l.animClock,6));l.sprite.transform.position=l.p+Vector2.up*(.12f+Mathf.Sin(l.animClock*3.2f)*.04f);float distance=(l.p-pos).magnitude;if(distance<reach)l.magnet=true;if(l.magnet){l.p=Vector2.MoveTowards(l.p,pos,(6+distance*2)*dt);l.sprite.transform.position=l.p;}if((l.p-pos).magnitude>.4f)continue;int kind=l.kind;float value=l.value;Dispose(l.sprite.gameObject);loot.RemoveAt(i);if(kind==4){CollectRelic((int)value);continue;}if(kind==0){xp+=value;Play(gemSound,.3f);}else if(kind==2)hp=Mathf.Min(maxHp,hp+value);else if(kind==3){foreach(var other in loot)if(other.kind==0)other.magnet=true;Toast("Todos os cristais estão vindo até você!");}else {OpenChest((int)value);return;}}
  if(xp>=XpRequired){xp-=XpRequired;level++;ChooseUpgrades();Play(levelSound);}}
 void ChooseUpgrades(){choices.Clear();var pool=new List<int>();for(int i=0;i<6;i++){if(weapons[i]<8)pool.Add(i);if(passives[i]<5)pool.Add(6+i);}for(int i=0;i<3&&pool.Count>0;i++){int j=UnityEngine.Random.Range(0,pool.Count);choices.Add(pool[j]);pool.RemoveAt(j);}if(choices.Count==0){choices.Add(12);choices.Add(13);}state=ScreenState.LevelUp;}
 public void SelectUpgrade(int id){ApplyUpgrade(id);state=ScreenState.Playing;if(xp>=XpRequired){xp-=XpRequired;level++;ChooseUpgrades();}}
 void ApplyUpgrade(int id){if(id<6)weapons[id]++;else if(id<12){passives[id-6]++;if(id==9){maxHp+=activeCurse==0?15:20;hp=Mathf.Min(maxHp,hp+20);}}else if(id==12)hp=Mathf.Min(maxHp,hp+50);else runCoins+=30;}
 void OpenChest(int bossType=-1){rewardBossType=bossType;chestOpenedAt=Time.unscaledTime;offerCurseAfterChest=bossType>=0&&activeCurse<0;runCoins+=25;for(int i=0;i<6;i++)if(weapons[i]>=8&&!evolved[i]&&passives[Catalog.EvolutionPassive[i]]>0){evolved[i]=true;chestMessage="EVOLUÇÃO\n"+EvolvedWeaponName(i)+"\n\nSua arma ganhou uma nova forma.";state=ScreenState.Chest;Play(levelSound);return;}
  var pool=new List<int>();for(int i=0;i<6;i++){if(weapons[i]>0&&weapons[i]<8)pool.Add(i);if(passives[i]>0&&passives[i]<5)pool.Add(i+6);}int id=pool.Count>0?pool[UnityEngine.Random.Range(0,pool.Count)]:13;ApplyUpgrade(id);chestMessage="TESOURO ENCONTRADO\n"+(id<6?WeaponName(id):id<12?Catalog.Passives[id-6]:"30 moedas extras")+"\n\n+25 moedas e uma melhoria!";state=ScreenState.Chest;Play(levelSound);}
 void AddHazard(Vector2 p,float radius,float damage,Element element=Element.Fire){if(hazards.Count>=35)return;hazards.Add(new Hazard{p=p,radius=radius,damage=damage,element=element,timer=1.25f,sprite=Sprite("Boss Warning",ArtBank.Ring,p,radius*2,new Color(1,.3f,.2f,.75f),-5)});}
 void UpdateHazards(float dt){mapHazardTimer+=dt;if(stageIndex==2&&!final3DActive&&mapHazardTimer>18){mapHazardTimer=0;AddHazard(pos+facing*2,2,16);}for(int i=hazards.Count-1;i>=0;i--){var h=hazards[i];h.timer-=dt;var hc=ElementColor(h.element);h.sprite.color=new Color(hc.r,hc.g,hc.b,.35f+Mathf.PingPong(h.timer*3,.55f));if(h.timer>0)continue;Burst(h.p,ElementColor(h.element),h.radius*2,.35f);ReactElement(h.p,Mathf.Min(h.radius,.95f),h.element,h.damage,true);if((h.p-pos).magnitude<h.radius&&invincible<=0){hp=Mathf.Max(0,hp-h.damage*(activeCurse==2?1.3f:1)*IncomingMultiplier);invincible=.7f;shake=.18f;Play(hitSound);if(h.element==Element.Fire)BurnPlayer(3,3);if(h.element==Element.Ice)playerChill=2;if(hp<=0)EndRun(false);}Dispose(h.sprite.gameObject);hazards.RemoveAt(i);}}
 void Burst(Vector2 p,Color c,float scale,float life=.2f,int kind=6){if(effects.Count>180)return;var f=new Fx{life=life,maxLife=life,scale=scale,color=c,kind=kind};f.sprite=Sprite("Effect",ArtBank.Ability(kind),p,scale,c,700);effects.Add(f);}
 void UpdateEffects(float dt){for(int i=effects.Count-1;i>=0;i--){var f=effects[i];f.life-=dt;if(f.life<=0){Dispose(f.sprite.gameObject);effects.RemoveAt(i);}else{f.sprite.sprite=ArtBank.Ability(f.kind,Mathf.Min(3,(int)((1-f.life/f.maxLife)*4)));f.sprite.color=new Color(f.color.r,f.color.g,f.color.b,f.life/f.maxLife*.65f);f.sprite.transform.localScale=Vector3.one*f.scale*(f.kind==3?.7f+.3f*(1-f.life/f.maxLife):1.1f-.1f*f.life/f.maxLife);}}}
 public void EndRun(bool win){if(final3DActive&&final3DTransition){final3DTransition=false;finalTransitionClock=FinalTransitionDuration;ShowFinal3D();}CancelPowerPreparation();hp=Mathf.Clamp(hp,0,maxHp);if(credited)return;credited=true;if(elementTraining||final3DDemo){runCoins=0;state=ScreenState.Result;chestMessage=final3DDemo?(win?"SOBERANO DERROTADO • TREINO":"TESTE FINAL 3D ENCERRADO"):"TREINO ENCERRADO";return;}runCoins=Mathf.RoundToInt((runCoins+kills/10+level*2+(win?150:0))*(1+save.perks[3]*.1f)*(activeCurse==1?1.5f:1));save.coins+=runCoins;save.totalKills+=kills;save.bestLevel=Mathf.Max(save.bestLevel,level);if(win)save.wins++;AnnounceDragonUnlocks(save.RefreshDragonMissions());if(!verifying)save.Store();state=ScreenState.Result;chestMessage=win?"A NOITE TERMINOU":"A NOITE TE ENCONTROU";}
 void Dispose(UnityEngine.Object obj){if(Application.isPlaying)UnityEngine.Object.Destroy(obj);else UnityEngine.Object.DestroyImmediate(obj);}
 void ReturnMenu(){ResetCampaign();ResetRescue();ResetRelicAttacks();ExitBuildLab();ResetExclusive();ResetFinal3D();CancelPowerPreparation();elementTraining=false;if(world!=null)Dispose(world.gameObject);state=ScreenState.Menu;cam.transform.position=new Vector3(0,0,-10);}
 void OnApplicationFocus(bool focus){if(!focus)Cursor.visible=true;if(!focus&&!verifying&&(state==ScreenState.Playing||state==ScreenState.StageRescue))state=ScreenState.Paused;}
 void OnApplicationQuit(){ExitBuildLab();Cursor.visible=true;if(!verifying){SaveMenuSettings();save?.Store();}}
 // Called only by the editor verification task, without touching the player's save.
 public string VerifyGameplay(){var original=save;verifying=true;save=new SaveData();StartRun();for(int i=0;i<6;i++){weapons[i]=8;passives[i]=2;}hp=maxHp=100000;for(int step=0;step<2400;step++){Tick(.05f);if(state==ScreenState.LevelUp)SelectUpgrade(choices[0]);if(state==ScreenState.Chest)state=ScreenState.Playing;}if(kills<1)throw new Exception("No enemy kills during simulation");if(enemies.Count>240)throw new Exception("Enemy limit exceeded");int verifiedKills=kills;OpenChest();if(!evolved[0])throw new Exception("Weapon evolution failed");state=ScreenState.Playing;xp=XpRequired+1;UpdateLoot(.05f);if(state!=ScreenState.LevelUp)throw new Exception("Level-up choice failed");SelectUpgrade(choices[0]);time=Duration;SpawnWaves(.05f);if(finalBoss==null)throw new Exception("Final boss did not spawn");Damage(finalBoss,finalBoss.maxHp+1);if(state!=ScreenState.Result||save.wins!=1)throw new Exception("Victory flow failed");hp=-6;EndRun(false);if(hp<0)throw new Exception("Negative health regression");save=original;verifying=false;ReturnMenu();return "PASS: 120 simulated seconds; "+verifiedKills+" kills; level-up; evolution; final boss; victory; health clamping; entity limits. "+VerifyMainMenu()+" "+VerifyDragonSystems()+" "+VerifyElements()+" "+VerifyAnimationPolish()+" "+VerifyAiming()+" "+VerifyDragonMissions()+" "+VerifyRelics()+" "+VerifyPowerPreparation()+" "+VerifyIceOwnership()+" "+VerifyPowerUpHub()+" "+VerifyFinal3D()+" "+VerifyNewHeroes()+" "+VerifyCombatProximity()+" "+VerifyManualAttack()+" "+VerifyExclusive()+" "+VerifyBuildLab()+" "+VerifyRelicAttacks()+" "+VerifyJourneyFeatures()+" "+VerifyFavorites()+" "+VerifyEnemyFSM();}
}
